#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Limit on number of arguments (including program name) is 65
    if (argc > 65) {
        puts("TOO_MANY");
        return 0;
    }
    // Need at least one argument besides program name
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    // Check length constraints (max 1024 characters per argument)
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    // Find longest common prefix among all arguments
    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && s[j] && first[j] && s[j] == first[j]) {
            ++j;
        }
        prefix_len = j;
        if (prefix_len == 0) {
            break;
        }
    }
    // Output the prefix followed by a newline
    fwrite(first, 1, prefix_len, stdout);
    putchar('\n');
    return 0;
}
